rows = [json.loads(l) for l in (base/"judging/judgeY-block2.jsonl").read_text(encoding="utf-8").splitlines()]
assert len(rows) == len(SCORES) == 122
out = []
for r, (d, c, t, reason) in zip(rows, SCORES):
    total = d + c + t
    out.append({"anon_id": r["anon_id"], "direction": d, "claims": c, "timing": t, "total": total, "pass": total >= 4, "reason": reason})
with open(base/"judging/judgeY2-scores.jsonl", "w", encoding="utf-8") as f:
    for o in out:
        f.write(json.dumps(o, ensure_ascii=False) + "\n")
# self-verify: re-read, parse, check sum and order
back = [json.loads(l) for l in (base/"judging/judgeY2-scores.jsonl").read_text(encoding="utf-8").splitlines()]
assert len(back) == 122
assert [b["anon_id"] for b in back] == [r["anon_id"] for r in rows]
for b in back:
    assert abs(b["direction"] + b["claims"] + b["timing"] - b["total"]) < 1e-9, b
    assert b["pass"] == (b["total"] >= 4), b
print("OK lines", len(back), "pass", sum(1 for b in back if b["pass"]), "null", sum(1 for b in back if b["total"] is None))
